/*
 * Stands in for a worklet the Worklets Babel plugin hoists into
 * `react-native-worklets/.worklets/<hash>.js`. The file name is the worklet hash, which
 * is the id a Worklet Runtime asks `__r` for, so the bundler has to map it to a module id.
 */

export default (function fixtureWorkletFactory([greeting]) {
  const worklet = function () {
    'worklet';
    globalThis.__WORKLET_EXECUTED__ = greeting;
    return greeting;
  };
  worklet.__workletHash = 10110358253470;
  return worklet;
});
